import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>网上来的 WebP 图片，常常要先变成 PNG 才能编辑、打印，或者在老软件里打开。转换只要几秒钟，结果是一份完美的副本。</p>\n<p>不用操心画质滑块，因为 PNG 是无损的。上传、转换、下载，像素原样保留。</p>\n<p>这篇指南一步一步带你走完流程，并给出能确认转换成功的检查方法。</p>\n<h2 id=\"before-you-start\">开始之前：先想清楚为什么要转</h2>\n<p>问问自己，PNG 是用来做什么的。编辑、打印、兼容老软件，都是好理由。想让文件更小就不是，因为 PNG 比 WebP 大。</p>\n<p>先确认是不是真的需要 PNG。很多现代工具直接接受 WebP，转成 PNG 只会增加体积，画质并不会变好。</p>\n<p>找一份手头最好的 WebP 原件。PNG 会原样保留它，瑕疵也一起保留，所以要从画质最高的副本开始。</p>\n<p>单个文件最大支持 25MB，高清下载图和大尺寸截图都不用提前处理，直接就能转。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 WebP 转 PNG 工具</h2>\n<p>在浏览器里打开 <a href=\"/zh/webp-zhuan-png/\">WebP 转 PNG 工具</a>。Windows、Mac、Linux、ChromeOS、安卓和 iOS 都能用。</p>\n<p>页面上只有上传区和转换按钮，没有画质滑块，因为 PNG 是无损的，本来就没有什么画质档位可选。</p>\n<p>不用注册账号，文件也不会上传。转换就在你的设备上完成，私人图片和下载文件也不用担心外泄。</p>\n<p>用手机的话，直接在手机浏览器里打开这个页面就行。点一下上传区，就能从下载文件夹或相册里选 WebP 文件。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 WebP 文件</h2>\n<p>把 WebP 文件拖到上传区，或者点一下打开文件选择器。一次选多个文件，就能批量转换。</p>\n<p>每个文件都会显示为一张卡片，带有缩略图、尺寸和文件大小。快速扫一眼，就能确认传对了文件，没有多余的混进来。</p>\n<p>有些网站保存图片时不带文件后缀。这些文件照样能转，因为工具是按文件实际内容来识别的，不看文件名。</p>\n<p>电脑上还能用 Ctrl+V 直接粘贴剪贴板里的图片。WebP 图片在别的软件里复制好之后，这个办法很方便。</p>\n<h2 id=\"step-3-convert\">第 3 步：转换文件</h2>\n<p>点“转换”按钮。工具会解码每个 WebP，把它画到画布上，再编码成 PNG。</p>\n<p>转换很快，每张通常只要一两秒。文件越大花的时间越长一点，因为要无损编码的像素更多。</p>\n<p>每张卡片都会更新，显示新的 PNG 大小和原来的 WebP 大小。PNG 大得多是正常的，照片常常是 WebP 的五到十倍。</p>\n<p>某个文件失败了就读一下报错信息。损坏的 WebP 或改错名字的文件是最常见的原因，整批里其余的文件会继续转换。</p>\n<h2 id=\"step-4-confirm-transparency\">第 4 步：确认透明度还在</h2>\n<p>点标志卡片上的“对比”，就能并排看到 WebP 和 PNG。放大看边缘，确认透明度干净。</p>\n<p>留意标志周围的光晕或毛边。边缘干净说明透明通道原样复制了，这就是我们要的结果。</p>\n<p>柔和的阴影也要检查。投影应该渐渐淡出，而不是一层一层地断开，分层就说明哪里出了问题。</p>\n<p>哪里看着不一样，就重新上传原 WebP 再转一次。转换应该是精确的，看得见的差别就意味着有问题。</p>\n<h2 id=\"step-5-download\">第 5 步：下载 PNG 文件</h2>\n<p>点单张卡片上的“下载”，就能保存这一张 PNG。文件名保持原名，只把后缀换成 .png。</p>\n<p>批量转换时，点“全部下载”可以拿到一个 ZIP，里面装着所有转好的 PNG。这比一张一张下载快得多。</p>\n<p>用之前先检查一遍下载好的文件。在看图软件里打开一张 PNG，确认显示正常，也确认它能在你需要的软件里打开。</p>\n<p>原 WebP 文件也留着。PNG 永远变不回完美的 WebP，原件就是你的保险。</p>\n<ol>\n<li>打开 WebP 转 PNG 工具，上传 WebP 文件。</li>\n<li>点“转换”，等每张卡片完成。</li>\n<li>用对比功能确认透明度还在。</li>\n<li>单张下载 PNG，或整批打包成 ZIP 下载。</li>\n</ol>\n<h2 id=\"converting-a-batch\">批量转换 WebP 图片</h2>\n<p>在文件选择器里一次选中多个 WebP 文件。它们会全部进入队列，点一下就能全部转成 PNG。</p>\n<p>批量运行时留意总大小。一批 WebP 照片转成 PNG 后，ZIP 可能变得非常大，先确认目的地能不能处理。</p>\n<p>下载整批之前，先用对比查看器抽查一两个文件。确认透明度还在，颜色也对得上。</p>\n<p>批量下载的 ZIP 解压到一个新文件夹里。转好的 PNG 和原 WebP 混在一个文件夹里，以后很容易搞混。</p>\n<h2 id=\"using-png-for-editing\">用 PNG 来编辑</h2>\n<p>在你喜欢的编辑器里打开 PNG。Photoshop、Figma、Canva 和 PowerPoint 都原生接受 PNG，无损格式反复保存也不会坏。</p>\n<p>在 PNG 版本上加文字、标注或叠加层。每次保存图片都和上一次一样锐利，不会累积损伤。</p>\n<p>完成后再按目的地的要求导出。网页要 WebP 或 JPG，打印店可能就要 PNG 本身。</p>\n<p>导出后留着 PNG 母版。以后还要再导出一次的话，可以直接从 PNG 开始，不用重新打开原 WebP。</p>\n<h2 id=\"fixing-problems\">常见问题怎么修</h2>\n<p>PNG 比预想的大得多，对照片来说很正常。PNG 原样保存每个像素，细节丰富的照片本来就需要很多字节。</p>\n<p>颜色看着偏移了，可能是源 WebP 的色彩配置没能保留下来。把 PNG 和 WebP 仔细对比一下，偏移很要紧就留着 WebP。</p>\n<p>某个文件转失败了，先确认它是不是真正的 WebP。没有后缀的文件可能是伪装的 JPG 或 PNG，工具是按内容来判断的。</p>\n<p>动态 WebP 转出来变成静态图，这是正常的。转换器只取第一帧，因为 PNG 存不了动画。</p>\n<h2 id=\"mobile-tips\">手机和平板上的小技巧</h2>\n<p>手机上点一下上传区，从下载文件夹或相册里选 WebP 文件。转换就在手机上完成，PNG 会下载到你的设备里。</p>\n<p>手机上批量别贪多，大 PNG 在手机处理器上编码比较慢。一次转五张左右比较舒服。</p>\n<p>下载的文件在手机的“下载”文件夹里。iPhone 在“文件”应用里找，安卓在文件管理器里找。</p>\n<p>要转一大批，还是用电脑。更快的处理器和更大的屏幕，处理很多文件要轻松得多。</p>\n<h2 id=\"webp-for-photoshop\">为 Photoshop 转换 WebP</h2>\n<p>Photoshop 现在支持 WebP 了，但很多插件和批处理操作还是只认 PNG。导入前转成 PNG，就能避开打断工作流程的意外。</p>\n<p>把 WebP 文件转成 PNG，再在 Photoshop 里打开。无损格式能处理图层、蒙版和调整，每次保存都不会退化。</p>\n<p>一批图片的话，先全部转好，再一起打开 PNG。这样 Photoshop 会话会很顺畅，不用做到一半停下来逐个转换。</p>\n<p>完成后的作品按网上用途导出为 WebP 或 JPG。PNG 是工作格式，导出格式则取决于图片最终放在哪里。</p>\n<p>导出后把 PNG 母版留在项目文件夹里。客户要求改动时，母版已经备好，导出文件只是交付用的副本。</p>\n<h2 id=\"webp-for-powerpoint\">为 PowerPoint 转换 WebP</h2>\n<p>老版 PowerPoint 显示不了 WebP 图片，带 WebP 照片的幻灯片在演示电脑上可能显示破损图标。先转成 PNG 就能消除这个风险。</p>\n<p>放进演示文稿之前，先把 WebP 图片转成 PNG。PNG 在所有版本的 PowerPoint 里都能干净地嵌入，幻灯片在哪里打开都正常。</p>\n<p>图片多的文稿，整批一起转。批量转换几分钟就能完成，转好的 PNG 直接拖进幻灯片就行。</p>\n<p>转换后看一下整份文稿的大小。超过 50MB 的文稿发邮件或上传都费劲，文件太大就先压缩一下图片。</p>\n<p>演讲前先在演示电脑上测试一下文稿。笔记本上看着正常的幻灯片，在老机器上可能显示破损图片，提前测试就能发现。</p>\n<h2 id=\"webp-for-print-shop\">为打印店转换 WebP</h2>\n<p>打印店只认 JPG 或 PNG，拿着 WebP 去可能被系统拒绝。发文件之前先转成 PNG，再确认一下打印店的具体要求。</p>\n<p>为打印而转换时要保留完整分辨率。800 像素宽的图片印 3 寸很清晰，印 10 寸就糊了，打印尺寸要和像素数匹配。</p>\n<p>转换后检查一下颜色，因为 WebP 和 PNG 处理色彩配置的方式略有不同。快速对比一下，就能确认打印颜色和屏幕颜色一致。</p>\n<p>带文字的打印文档，PNG 是正确的目标格式。无损格式让每个字母的边缘在纸上都锐利清晰，合同和表单尤其需要这一点。</p>\n<p>重要的活儿先印一张小样试试。一张小样就能确认颜色和清晰度，再决定要不要下大单。</p>\n<h2 id=\"webp-for-form\">为表单转换 WebP</h2>\n<p>上传表单只接受 JPG 和 PNG，WebP 文件会直接被弹回来。上传前先转成 PNG，再看一下表单的具体规则。</p>\n<p>表单有文件大小上限时，PNG 可能太大了。一张 PNG 照片可能有好几 MB，同样图片的 JPG 却只有它的零头。</p>\n<p>PNG 太大了，就把 WebP 转成 JPG。<a href=\"/zh/webp-zhuan-jpg/\">WebP 转 JPG 工具</a>转出来的文件更小，到处也都能打开。</p>\n<p>尺寸也要看，不只是格式。表单要求特定像素尺寸时，格式对了、形状不对的图片同样会被拒绝。</p>\n<p>尽早上传转换好的图片，别拖到截止日期。最后一刻才转换，出了问题没有时间修，提前上传还有机会再试一次。</p>\n<h2 id=\"webp-from-chat\">转换聊天里收到的 WebP</h2>\n<p>图片常常以 WebP 文件的形式发到聊天里，在电脑上却打不开。朋友从网站上发来一张照片，你的看图软件却显示一个破损图标。</p>\n<p>先把图片保存到设备上，再拖进转换器。直接从聊天软件里转换基本行不通，因为文件必须先存在你的设备上。</p>\n<p>保存后检查一下画质。聊天软件常常会自动压缩图片，保存下来的文件可能已经比原图画质低了。</p>\n<p>转换完如果别人也需要，就把 PNG 发回聊天里。PNG 在群里的每个人那儿都能打开，原来的 WebP 有一半人打不开。</p>\n<p>原消息留着当备份。万一转换出了问题，还能重新下载图片再试，不用麻烦发件人重发一遍。</p>\n<h2 id=\"batch-for-project\">为项目批量转换</h2>\n<p>一个项目常常需要把一整套 WebP 图片一次转成 PNG。批量转换几分钟就能完成，转好的 PNG 直接拖进设计工具就行。</p>\n<p>转换前按用途把图片分好类。标志、照片和截图之后的处理可能不同，先分好类，项目才有条理。</p>\n<p>下载整批之前，先用对比查看器抽查一两个文件。确认透明度还在，颜色也和原件对得上。</p>\n<p>批量下载的 ZIP 解压到项目文件夹里。新文件夹能让转好的 PNG 和 WebP 原件分开存放。</p>\n<p>转换后把 WebP 原件存进归档文件夹。它们是网上用的最好画质版本，项目以后需要别的格式还能再转。</p>\n<h2 id=\"webp-for-school-project\">为学校作业转换 WebP</h2>\n<p>学校作业经常要用到网上的图片，而这些图片通常是 WebP。学校电脑上的老软件可能显示不了，所以先转成 PNG 更稳妥。</p>\n<p>放进作业之前，先把图片转成 PNG。PNG 在 PowerPoint、Word 和 Google 幻灯片里都能干净嵌入，作业在任何一台学校电脑上打开都正常。</p>\n<p>图片多的作业，整批一起转。批量转换几分钟就能完成，转好的 PNG 直接拖进幻灯片就行。</p>\n<p>转换后检查一遍图片。快速看一下每一张，确认都能正常显示，展示那天就不会出现坏图。</p>\n<p>记得在作业里注明图片来源。转过格式的图片依然属于原作者，规范的引用是良好的学术习惯。</p>\n<p>整个流程就是：上传、转换、确认、下载。想了解背后的原理，可以看<a href=\"/zh/blog/webp-zhuan-png-wanquan-zhinan/\">WebP 转 PNG 完全指南</a>；编辑方面的问题可以看<a href=\"/zh/blog/webp-zhuan-png-bianji-jianrongxing/\">WebP 转 PNG：编辑、透明度与兼容性</a>。如果要的是更小的文件，<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>更合适。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"转换后怎么确认透明度保留下来了？","answer":"点标志卡片上的“对比”，就能并排看到 WebP 和 PNG。放大看边缘，找找有没有光晕或毛边，出现就说明有问题。柔和的阴影也要检查，应该渐渐淡出。边缘干净就说明透明通道原样复制了。"},{"question":"WebP 截图转 PNG 会损失画质吗？","answer":"不会。转换是原样复制每个像素，WebP 截图转成的 PNG 像素相同，文字也一样锐利。PNG 是大了点，但图片完全一样。要编辑的截图，这份精确性值得多占的体积。"},{"question":"转换接受的单个 WebP 文件最大是多大？","answer":"每个 WebP 文件最大 25MB，高清下载图和大尺寸截图都能覆盖。转换在你的设备上运行，大文件按本地速度处理，不用等上传。"},{"question":"没有文件后缀的 WebP 文件能转换吗？","answer":"可以。有些网站保存图片时不带后缀，但工具是按文件实际内容来识别的，不看文件名。直接把文件拖进去，解码器会认出它是 WebP。就算它其实是 JPG 或 PNG，工具也能处理。"},{"question":"WebP 转 PNG 在手机上能用吗？","answer":"可以。在手机浏览器里打开工具，从下载文件夹或相册里选 WebP 文件，再下载转好的 PNG。转换就在手机上完成，文件会下载到你的设备里。手机上批量别贪多，大 PNG 在手机上编码比较慢。"},{"question":"什么时候选 WebP 转 PNG，而不是 WebP 转 JPG？","answer":"需要保留透明度，或者打算反复编辑图片时选 PNG，因为 PNG 无损，在每个编辑器里都能打开。目的地有明确要求，或者文件大小更重要时选 JPG，照片用 JPG 要小得多。"}];
